namespace SaaSPlatform.Api.Modules.Procurement.Application;

#pragma warning disable CA1304, CA1311, CA1862

public sealed record ProcurementPage<T>(IReadOnlyList<T> Items, int Page, int PageSize, int Total);
public sealed record ProcurementListQuery(string? Search, Guid? SiteId, int? Status, int Page = 1, int PageSize = 25);
public sealed record SupplierInput(string Code, string NameEn, string? NameAr, string? ContactPerson, string? Email, string? Phone, string? AlternatePhone, string? TaxNumber, string? CommercialRegistrationNumber, string? Address, string? City, string? Country, string? Website, string? PaymentTerms, string DefaultCurrency, string? Notes, Guid Version);
public sealed record SupplierStatusInput(bool IsActive, Guid Version);
public sealed record SupplierPartInput(Guid PartId, string? SupplierPartNumber, decimal? LastUnitPrice, string Currency, decimal MinimumOrderQuantity, int LeadTimeDays, bool IsPreferred, Guid Version);
public sealed record RequisitionLineInput(Guid PartId, decimal Quantity, Guid? SuggestedSupplierId, decimal? EstimatedUnitPrice, string? Notes);
public sealed record RequisitionInput(Guid SiteId, Guid TargetWarehouseId, DateOnly RequestDate, DateOnly? NeedByDate, ProcurementPriority Priority, string BusinessJustification, string? Notes, IReadOnlyList<RequisitionLineInput> Lines, Guid Version);
public sealed record WorkflowInput(Guid Version, string? Comment);
public sealed record RequisitionReviewInput(Guid Version, bool Approve, string Comment);
public sealed record PurchaseOrderLineInput(Guid? SourceRequisitionLineId, Guid PartId, decimal Quantity, decimal UnitPrice, string? SupplierPartNumber);
public sealed record PurchaseOrderInput(Guid SupplierId, Guid SiteId, Guid DestinationWarehouseId, DateOnly OrderDate, DateOnly? ExpectedDeliveryDate, string Currency, string? PaymentTerms, string? Notes, IReadOnlyList<PurchaseOrderLineInput> Lines, Guid Version);
public sealed record PurchaseReceiptLineInput(Guid PurchaseOrderLineId, decimal Quantity, decimal UnitCost);
public sealed record PurchaseReceiptInput(Guid RequestId, DateOnly ReceiptDate, Guid StockLocationId, string? ReceiptNumber, string? SupplierReference, string? Notes, Guid PurchaseOrderVersion, IReadOnlyList<PurchaseReceiptLineInput> Lines);
public sealed record ProcurementDashboard(int DraftRequisitions, int AwaitingApproval, int ApprovedNotConverted, int OpenPurchaseOrders, int PartiallyReceivedOrders, int OverdueDeliveries, decimal PurchaseValueLast30Days, int LowStockItems, IReadOnlyList<PurchaseReceipt> RecentReceipts);

public interface IProcurementService
{
    Task<ProcurementDashboard> Dashboard(ClaimsPrincipal user, CancellationToken ct);
    Task<ProcurementPage<Supplier>> Suppliers(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct);
    Task<Supplier> Supplier(ClaimsPrincipal user, Guid id, CancellationToken ct);
    Task<Supplier> CreateSupplier(ClaimsPrincipal user, SupplierInput input, CancellationToken ct);
    Task<Supplier> UpdateSupplier(ClaimsPrincipal user, Guid id, SupplierInput input, CancellationToken ct);
    Task<Supplier> SetSupplierStatus(ClaimsPrincipal user, Guid id, SupplierStatusInput input, CancellationToken ct);
    Task<SupplierPart> UpsertSupplierPart(ClaimsPrincipal user, Guid supplierId, SupplierPartInput input, CancellationToken ct);
    Task<ProcurementPage<PurchaseRequisition>> Requisitions(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct);
    Task<PurchaseRequisition> Requisition(ClaimsPrincipal user, Guid id, CancellationToken ct);
    Task<PurchaseRequisition> CreateRequisition(ClaimsPrincipal user, RequisitionInput input, CancellationToken ct);
    Task<PurchaseRequisition> UpdateRequisition(ClaimsPrincipal user, Guid id, RequisitionInput input, CancellationToken ct);
    Task<PurchaseRequisition> SubmitRequisition(ClaimsPrincipal user, Guid id, WorkflowInput input, CancellationToken ct);
    Task<PurchaseRequisition> ReviewRequisition(ClaimsPrincipal user, Guid id, RequisitionReviewInput input, CancellationToken ct);
    Task<ProcurementPage<PurchaseOrder>> PurchaseOrders(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct);
    Task<PurchaseOrder> PurchaseOrder(ClaimsPrincipal user, Guid id, CancellationToken ct);
    Task<PurchaseOrder> CreatePurchaseOrder(ClaimsPrincipal user, PurchaseOrderInput input, CancellationToken ct);
    Task<PurchaseOrder> UpdatePurchaseOrder(ClaimsPrincipal user, Guid id, PurchaseOrderInput input, CancellationToken ct);
    Task<PurchaseOrder> IssuePurchaseOrder(ClaimsPrincipal user, Guid id, WorkflowInput input, CancellationToken ct);
    Task<PurchaseOrder> CancelPurchaseOrder(ClaimsPrincipal user, Guid id, WorkflowInput input, CancellationToken ct);
    Task<PurchaseOrder> ClosePurchaseOrder(ClaimsPrincipal user, Guid id, WorkflowInput input, CancellationToken ct);
    Task<PurchaseReceipt> ReceivePurchaseOrder(ClaimsPrincipal user, Guid purchaseOrderId, PurchaseReceiptInput input, CancellationToken ct);
    Task<ProcurementPage<PurchaseReceipt>> Receipts(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct);
    Task<IReadOnlyList<ProcurementActivity>> Activities(ClaimsPrincipal user, string entityType, Guid entityId, CancellationToken ct);
}

public sealed class ProcurementService(PlatformDbContext database, ICurrentTenant currentTenant, ISiteScopeAuthorizer scopes, IInventoryService inventory, IAuditWriter audit, TimeProvider clock) : IProcurementService
{
    private Guid TenantId => currentTenant.Id ?? throw new InvalidOperationException("Tenant context is required.");
    private DateTimeOffset Now => clock.GetUtcNow();

    public async Task<ProcurementDashboard> Dashboard(ClaimsPrincipal user, CancellationToken ct)
    {
        RequireAny(user, TenantPermissions.ProcurementDashboardView); var sites = AccessibleSites(user, TenantPermissions.ProcurementDashboardView);
        var requisitions = database.PurchaseRequisitions.Where(x => sites.Contains(x.SiteId)); var orders = database.PurchaseOrders.Where(x => sites.Contains(x.SiteId)); var receipts = database.PurchaseReceipts.AsNoTracking().Include(x => x.PurchaseOrder).Where(x => x.PurchaseOrder != null && sites.Contains(x.PurchaseOrder.SiteId)); var since = DateOnly.FromDateTime(Now.UtcDateTime.AddDays(-30));
        var low = await database.InventoryBalances.AsNoTracking().Include(x => x.Warehouse).Include(x => x.Part).Where(x => x.Warehouse != null && sites.Contains(x.Warehouse.SiteId) && x.Part != null && x.QuantityOnHand <= x.Part.ReorderPoint).Select(x => x.PartId).Distinct().CountAsync(ct);
        return new(await requisitions.CountAsync(x => x.Status == PurchaseRequisitionStatus.Draft, ct), await requisitions.CountAsync(x => x.Status == PurchaseRequisitionStatus.Submitted, ct), await requisitions.CountAsync(x => x.Status == PurchaseRequisitionStatus.Approved || x.Status == PurchaseRequisitionStatus.PartiallyConverted, ct), await orders.CountAsync(x => x.Status == PurchaseOrderStatus.Issued || x.Status == PurchaseOrderStatus.PartiallyReceived, ct), await orders.CountAsync(x => x.Status == PurchaseOrderStatus.PartiallyReceived, ct), await orders.CountAsync(x => x.ExpectedDeliveryDate < DateOnly.FromDateTime(Now.UtcDateTime) && (x.Status == PurchaseOrderStatus.Issued || x.Status == PurchaseOrderStatus.PartiallyReceived), ct), Money(await receipts.Where(x => x.ReceiptDate >= since).SumAsync(x => (decimal?)x.TotalCost, ct) ?? 0), low, await receipts.Include(x => x.Lines).OrderByDescending(x => x.CreatedAtUtc).Take(10).ToListAsync(ct));
    }

    public async Task<ProcurementPage<Supplier>> Suppliers(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct)
    {
        RequireTenant(user, TenantPermissions.ProcurementView); var source = database.Suppliers.AsNoTracking().Include(x => x.Parts).ThenInclude(x => x.Part).AsQueryable(); if (!string.IsNullOrWhiteSpace(query.Search)) { var s = query.Search.Trim().ToLower(); source = source.Where(x => x.Code.ToLower().Contains(s) || x.NameEn.ToLower().Contains(s) || (x.NameAr != null && x.NameAr.Contains(s))); } if (query.Status is { } status) source = source.Where(x => (int)x.Status == status); return await Page(source.OrderBy(x => x.Code), query, ct);
    }
    public async Task<Supplier> Supplier(ClaimsPrincipal user, Guid id, CancellationToken ct) { RequireTenant(user, TenantPermissions.ProcurementView); return await database.Suppliers.AsNoTracking().Include(x => x.Parts).ThenInclude(x => x.Part).SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new ResourceNotFoundException("Supplier was not found."); }
    public async Task<Supplier> CreateSupplier(ClaimsPrincipal user, SupplierInput input, CancellationToken ct) { RequireTenant(user, TenantPermissions.ProcurementSuppliersManage); ValidateSupplier(input); var code = Code(input.Code); if (await database.Suppliers.AnyAsync(x => x.Code == code, ct)) throw new ConflictException("Supplier code already exists."); var entity = new Supplier { Id = Guid.NewGuid(), TenantId = TenantId, Code = code, NameEn = Required(input.NameEn, "English name"), DefaultCurrency = Currency(input.DefaultCurrency) }; Apply(entity, input); database.Suppliers.Add(entity); Activity(nameof(Supplier), entity.Id, "Supplier.Created", null, entity.Status.ToString(), null, user); audit.Add("Procurement.SupplierCreated", nameof(Supplier), entity.Id); await Save(ct); return entity; }
    public async Task<Supplier> UpdateSupplier(ClaimsPrincipal user, Guid id, SupplierInput input, CancellationToken ct) { RequireTenant(user, TenantPermissions.ProcurementSuppliersManage); ValidateSupplier(input); var entity = await database.Suppliers.SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new ResourceNotFoundException("Supplier was not found."); Version(entity.Version, input.Version); var code = Code(input.Code); if (await database.Suppliers.AnyAsync(x => x.Id != id && x.Code == code, ct)) throw new ConflictException("Supplier code already exists."); entity.Code = code; Apply(entity, input); entity.Version = Guid.NewGuid(); Activity(nameof(Supplier), id, "Supplier.Updated", null, null, null, user); await Save(ct); return entity; }
    public async Task<Supplier> SetSupplierStatus(ClaimsPrincipal user, Guid id, SupplierStatusInput input, CancellationToken ct) { RequireTenant(user, TenantPermissions.ProcurementSuppliersManage); var entity = await database.Suppliers.SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new ResourceNotFoundException("Supplier was not found."); Version(entity.Version, input.Version); var from = entity.Status; entity.Status = input.IsActive ? SupplierStatus.Active : SupplierStatus.Inactive; entity.Version = Guid.NewGuid(); Activity(nameof(Supplier), id, "Supplier.StatusChanged", from.ToString(), entity.Status.ToString(), null, user); await Save(ct); return entity; }
    public async Task<SupplierPart> UpsertSupplierPart(ClaimsPrincipal user, Guid supplierId, SupplierPartInput input, CancellationToken ct) { RequireTenant(user, TenantPermissions.ProcurementSuppliersManage); var supplier = await database.Suppliers.SingleOrDefaultAsync(x => x.Id == supplierId, ct) ?? throw new ResourceNotFoundException("Supplier was not found."); _ = await database.SpareParts.SingleOrDefaultAsync(x => x.Id == input.PartId, ct) ?? throw new ValidationException("Spare part was not found."); if (input.LastUnitPrice < 0 || input.MinimumOrderQuantity <= 0 || input.LeadTimeDays < 0) throw new ValidationException("Supplier pricing values are invalid."); var entity = await database.SupplierParts.SingleOrDefaultAsync(x => x.SupplierId == supplierId && x.PartId == input.PartId, ct); if (entity is null) { entity = new() { Id = Guid.NewGuid(), TenantId = TenantId, SupplierId = supplierId, PartId = input.PartId, Currency = Currency(input.Currency) }; database.SupplierParts.Add(entity); } else Version(entity.Version, input.Version); if (input.IsPreferred) foreach (var other in await database.SupplierParts.Where(x => x.PartId == input.PartId && x.Id != entity.Id && x.IsPreferred).ToListAsync(ct)) { other.IsPreferred = false; other.Version = Guid.NewGuid(); } entity.SupplierPartNumber = Clean(input.SupplierPartNumber); entity.LastUnitPrice = input.LastUnitPrice is null ? null : Unit(input.LastUnitPrice.Value); entity.Currency = Currency(input.Currency); entity.MinimumOrderQuantity = input.MinimumOrderQuantity; entity.LeadTimeDays = input.LeadTimeDays; entity.IsPreferred = input.IsPreferred; entity.Version = Guid.NewGuid(); Activity(nameof(Supplier), supplier.Id, "Supplier.PartLinked", null, null, input.PartId.ToString(), user); await Save(ct); return entity; }

    public Task<ProcurementPage<PurchaseRequisition>> Requisitions(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct) => RequisitionPage(user, query, ct);
    private async Task<ProcurementPage<PurchaseRequisition>> RequisitionPage(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct) { RequireAny(user, TenantPermissions.ProcurementView); var sites = AccessibleSites(user, TenantPermissions.ProcurementView); var source = database.PurchaseRequisitions.AsNoTracking().Include(x => x.Site).Include(x => x.TargetWarehouse).Include(x => x.RequestedBy).Include(x => x.Lines).ThenInclude(x => x.Part).Where(x => sites.Contains(x.SiteId)); if (query.SiteId is { } site) source = source.Where(x => x.SiteId == site); if (query.Status is { } status) source = source.Where(x => (int)x.Status == status); if (!string.IsNullOrWhiteSpace(query.Search)) { var s = query.Search.Trim().ToLower(); source = source.Where(x => x.Number.ToLower().Contains(s) || x.BusinessJustification.ToLower().Contains(s)); } return await Page(source.OrderByDescending(x => x.CreatedAtUtc), query, ct); }
    public async Task<PurchaseRequisition> Requisition(ClaimsPrincipal user, Guid id, CancellationToken ct) { var entity = await RequisitionEntity(id, true, ct); RequireSite(user, TenantPermissions.ProcurementView, entity.SiteId); return entity; }
    public async Task<PurchaseRequisition> CreateRequisition(ClaimsPrincipal user, RequisitionInput input, CancellationToken ct) { ValidateRequisition(input); await ValidateSiteWarehouse(user, TenantPermissions.ProcurementRequisitionsCreate, input.SiteId, input.TargetWarehouseId, ct); await ValidateRequisitionLines(input.Lines, ct); await using var tx = await Transaction(ct); var entity = new PurchaseRequisition { Id = Guid.NewGuid(), TenantId = TenantId, Number = await NextNumber("PR", ct), SiteId = input.SiteId, TargetWarehouseId = input.TargetWarehouseId, RequestedById = Actor(user), Status = PurchaseRequisitionStatus.Draft, BusinessJustification = string.Empty }; Apply(entity, input); database.PurchaseRequisitions.Add(entity); AddRequisitionLines(entity, input.Lines); Activity(nameof(PurchaseRequisition), entity.Id, "Requisition.Created", null, entity.Status.ToString(), null, user); await Save(ct); if (tx is not null) await tx.CommitAsync(ct); return await RequisitionEntity(entity.Id, true, ct); }
    public async Task<PurchaseRequisition> UpdateRequisition(ClaimsPrincipal user, Guid id, RequisitionInput input, CancellationToken ct) { ValidateRequisition(input); var entity = await RequisitionEntity(id, true, ct); RequireSite(user, TenantPermissions.ProcurementRequisitionsCreate, entity.SiteId); Version(entity.Version, input.Version); if (entity.Status is not (PurchaseRequisitionStatus.Draft or PurchaseRequisitionStatus.Rejected)) throw new ConflictException("Only draft or rejected requisitions can be edited."); await ValidateSiteWarehouse(user, TenantPermissions.ProcurementRequisitionsCreate, input.SiteId, input.TargetWarehouseId, ct); await ValidateRequisitionLines(input.Lines, ct); database.PurchaseRequisitionLines.RemoveRange(entity.Lines); entity.Lines.Clear(); entity.SiteId = input.SiteId; entity.TargetWarehouseId = input.TargetWarehouseId; entity.Status = PurchaseRequisitionStatus.Draft; entity.ReviewComment = null; entity.ReviewedAtUtc = null; entity.ReviewedById = null; Apply(entity, input); AddRequisitionLines(entity, input.Lines); entity.Version = Guid.NewGuid(); Activity(nameof(PurchaseRequisition), id, "Requisition.Updated", null, entity.Status.ToString(), null, user); await Save(ct); return await RequisitionEntity(id, true, ct); }
    public async Task<PurchaseRequisition> SubmitRequisition(ClaimsPrincipal user, Guid id, WorkflowInput input, CancellationToken ct) { var entity = await RequisitionEntity(id, true, ct); RequireSite(user, TenantPermissions.ProcurementRequisitionsCreate, entity.SiteId); Version(entity.Version, input.Version); if (entity.Status != PurchaseRequisitionStatus.Draft) throw new ConflictException("Only a draft requisition can be submitted."); if (entity.Lines.Count == 0) throw new ValidationException("At least one requisition line is required."); Transition(entity, PurchaseRequisitionStatus.Submitted, "Requisition.Submitted", input.Comment, user); await Save(ct); return entity; }
    public async Task<PurchaseRequisition> ReviewRequisition(ClaimsPrincipal user, Guid id, RequisitionReviewInput input, CancellationToken ct) { var entity = await RequisitionEntity(id, true, ct); RequireSite(user, TenantPermissions.ProcurementRequisitionsReview, entity.SiteId); Version(entity.Version, input.Version); if (entity.Status != PurchaseRequisitionStatus.Submitted) throw new ConflictException("Only a submitted requisition can be reviewed."); var actor = Actor(user); if (actor == entity.RequestedById) throw new ConflictException("A requester cannot approve or reject their own requisition."); if (!input.Approve && string.IsNullOrWhiteSpace(input.Comment)) throw new ValidationException("A rejection reason is required."); entity.ReviewedById = actor; entity.ReviewedAtUtc = Now; entity.ReviewComment = Required(input.Comment, "Review comment"); Transition(entity, input.Approve ? PurchaseRequisitionStatus.Approved : PurchaseRequisitionStatus.Rejected, input.Approve ? "Requisition.Approved" : "Requisition.Rejected", input.Comment, user); await Save(ct); return entity; }

    public async Task<ProcurementPage<PurchaseOrder>> PurchaseOrders(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct) { RequireAny(user, TenantPermissions.ProcurementView); var sites = AccessibleSites(user, TenantPermissions.ProcurementView); var source = database.PurchaseOrders.AsNoTracking().Include(x => x.Supplier).Include(x => x.Site).Include(x => x.DestinationWarehouse).Include(x => x.Lines).ThenInclude(x => x.Part).Where(x => sites.Contains(x.SiteId)); if (query.SiteId is { } site) source = source.Where(x => x.SiteId == site); if (query.Status is { } status) source = source.Where(x => (int)x.Status == status); if (!string.IsNullOrWhiteSpace(query.Search)) { var s = query.Search.Trim().ToLower(); source = source.Where(x => x.Number.ToLower().Contains(s) || (x.Supplier != null && x.Supplier.NameEn.ToLower().Contains(s))); } return await Page(source.OrderByDescending(x => x.CreatedAtUtc), query, ct); }
    public async Task<PurchaseOrder> PurchaseOrder(ClaimsPrincipal user, Guid id, CancellationToken ct) { var entity = await OrderEntity(id, true, ct); RequireSite(user, TenantPermissions.ProcurementView, entity.SiteId); return entity; }
    public async Task<PurchaseOrder> CreatePurchaseOrder(ClaimsPrincipal user, PurchaseOrderInput input, CancellationToken ct) { ValidateOrder(input); await ValidateSiteWarehouse(user, TenantPermissions.ProcurementPurchaseOrdersCreate, input.SiteId, input.DestinationWarehouseId, ct); var supplier = await ActiveSupplier(input.SupplierId, ct); await using var tx = await Transaction(ct); var entity = new PurchaseOrder { Id = Guid.NewGuid(), TenantId = TenantId, Number = await NextNumber("PO", ct), SupplierId = supplier.Id, SiteId = input.SiteId, DestinationWarehouseId = input.DestinationWarehouseId, CreatedById = Actor(user), Status = PurchaseOrderStatus.Draft, Currency = Currency(input.Currency) }; await ApplyOrder(entity, input, user, false, ct); database.PurchaseOrders.Add(entity); Activity(nameof(PurchaseOrder), entity.Id, "PurchaseOrder.Created", null, entity.Status.ToString(), null, user); await Save(ct); await RefreshRequisitionStatuses(entity.Lines, user, ct); await Save(ct); if (tx is not null) await tx.CommitAsync(ct); return await OrderEntity(entity.Id, true, ct); }
    public async Task<PurchaseOrder> UpdatePurchaseOrder(ClaimsPrincipal user, Guid id, PurchaseOrderInput input, CancellationToken ct) { ValidateOrder(input); var entity = await OrderEntity(id, true, ct); RequireSite(user, TenantPermissions.ProcurementPurchaseOrdersManage, entity.SiteId); Version(entity.Version, input.Version); if (entity.Status != PurchaseOrderStatus.Draft) throw new ConflictException("Only draft purchase orders can be edited."); await ValidateSiteWarehouse(user, TenantPermissions.ProcurementPurchaseOrdersManage, input.SiteId, input.DestinationWarehouseId, ct); _ = await ActiveSupplier(input.SupplierId, ct); await using var tx = await Transaction(ct); await RestoreConversions(entity.Lines, ct); database.PurchaseOrderLines.RemoveRange(entity.Lines); entity.Lines.Clear(); entity.SupplierId = input.SupplierId; entity.SiteId = input.SiteId; entity.DestinationWarehouseId = input.DestinationWarehouseId; await ApplyOrder(entity, input, user, true, ct); entity.Version = Guid.NewGuid(); Activity(nameof(PurchaseOrder), id, "PurchaseOrder.Updated", null, null, null, user); await Save(ct); await RefreshRequisitionStatuses(entity.Lines, user, ct); await Save(ct); if (tx is not null) await tx.CommitAsync(ct); return await OrderEntity(id, true, ct); }
    public Task<PurchaseOrder> IssuePurchaseOrder(ClaimsPrincipal user, Guid id, WorkflowInput input, CancellationToken ct) => ChangeOrder(user, id, input, PurchaseOrderStatus.Draft, PurchaseOrderStatus.Issued, "PurchaseOrder.Issued", ct);
    public async Task<PurchaseOrder> CancelPurchaseOrder(ClaimsPrincipal user, Guid id, WorkflowInput input, CancellationToken ct) { var entity = await OrderEntity(id, true, ct); RequireSite(user, TenantPermissions.ProcurementPurchaseOrdersManage, entity.SiteId); Version(entity.Version, input.Version); if (entity.Status is not (PurchaseOrderStatus.Draft or PurchaseOrderStatus.Issued) || entity.Lines.Any(x => x.ReceivedQuantity > 0)) throw new ConflictException("Only an unreceived draft or issued purchase order can be cancelled."); await using var tx = await Transaction(ct); await RestoreConversions(entity.Lines, ct); Change(entity, PurchaseOrderStatus.Cancelled, "PurchaseOrder.Cancelled", input.Comment, user); await Save(ct); await RefreshRequisitionStatuses(entity.Lines, user, ct); await Save(ct); if (tx is not null) await tx.CommitAsync(ct); return entity; }
    public Task<PurchaseOrder> ClosePurchaseOrder(ClaimsPrincipal user, Guid id, WorkflowInput input, CancellationToken ct) => ChangeOrder(user, id, input, PurchaseOrderStatus.FullyReceived, PurchaseOrderStatus.Closed, "PurchaseOrder.Closed", ct);

    public async Task<PurchaseReceipt> ReceivePurchaseOrder(ClaimsPrincipal user, Guid purchaseOrderId, PurchaseReceiptInput input, CancellationToken ct)
    {
        if (input.RequestId == Guid.Empty) throw new ValidationException("A request ID is required for retry safety."); if (input.Lines.Count == 0) throw new ValidationException("At least one receipt line is required."); var duplicate = await database.PurchaseReceipts.AsNoTracking().Include(x => x.Lines).SingleOrDefaultAsync(x => x.RequestId == input.RequestId, ct); if (duplicate is not null) return duplicate;
        var order = await OrderEntity(purchaseOrderId, true, ct); RequireSite(user, TenantPermissions.ProcurementReceivingCreate, order.SiteId); Version(order.Version, input.PurchaseOrderVersion); if (order.Status is not (PurchaseOrderStatus.Issued or PurchaseOrderStatus.PartiallyReceived)) throw new ConflictException("Only an issued purchase order can be received."); var location = await database.WarehouseStockLocations.SingleOrDefaultAsync(x => x.Id == input.StockLocationId && x.WarehouseId == order.DestinationWarehouseId && x.IsActive, ct) ?? throw new ValidationException("An active stock location in the destination warehouse is required."); if (input.Lines.Select(x => x.PurchaseOrderLineId).Distinct().Count() != input.Lines.Count) throw new ValidationException("A purchase-order line can appear only once per receipt.");
        await using var tx = await Transaction(ct); var entity = new PurchaseReceipt { Id = Guid.NewGuid(), TenantId = TenantId, RequestId = input.RequestId, PurchaseOrderId = order.Id, ReceiptNumber = string.IsNullOrWhiteSpace(input.ReceiptNumber) ? await NextNumber("GRN", ct) : Required(input.ReceiptNumber, "Receipt number"), SupplierReference = Clean(input.SupplierReference), ReceiptDate = input.ReceiptDate, WarehouseId = order.DestinationWarehouseId, StockLocationId = location.Id, ReceivedById = Actor(user), Notes = Clean(input.Notes) }; database.PurchaseReceipts.Add(entity);
        foreach (var row in input.Lines) { Positive(row.Quantity, "Received quantity"); if (row.UnitCost < 0) throw new ValidationException("Unit cost cannot be negative."); var line = order.Lines.SingleOrDefault(x => x.Id == row.PurchaseOrderLineId) ?? throw new ValidationException("Purchase-order line was not found."); if (line.ReceivedQuantity + row.Quantity > line.OrderedQuantity) throw new ConflictException("Receipt quantity exceeds the remaining ordered quantity."); var stock = await inventory.ReceiveForProcurement(user, new StockReceiptInput(Derive(input.RequestId, line.Id), order.DestinationWarehouseId, location.Id, line.PartId, entity.ReceiptNumber, order.Supplier?.NameEn, input.SupplierReference, input.ReceiptDate, row.Quantity, row.UnitCost, input.Notes), ct); var total = Money(row.Quantity * row.UnitCost); var receiptLine = new PurchaseReceiptLine { Id = Guid.NewGuid(), TenantId = TenantId, PurchaseReceiptId = entity.Id, PurchaseOrderLineId = line.Id, StockReceiptId = stock.Id, Quantity = row.Quantity, UnitCost = Unit(row.UnitCost), TotalCost = total }; database.PurchaseReceiptLines.Add(receiptLine); entity.Lines.Add(receiptLine); entity.TotalCost += total; line.ReceivedQuantity += row.Quantity; }
        var from = order.Status; order.Status = order.Lines.All(x => x.ReceivedQuantity == x.OrderedQuantity) ? PurchaseOrderStatus.FullyReceived : PurchaseOrderStatus.PartiallyReceived; order.Version = Guid.NewGuid(); Activity(nameof(PurchaseOrder), order.Id, order.Status == PurchaseOrderStatus.FullyReceived ? "PurchaseOrder.FullyReceived" : "PurchaseOrder.PartiallyReceived", from.ToString(), order.Status.ToString(), entity.ReceiptNumber, user); Activity(nameof(PurchaseReceipt), entity.Id, "Receipt.Posted", null, null, order.Number, user); audit.Add("Procurement.ReceiptPosted", nameof(PurchaseReceipt), entity.Id, new { order.Id, entity.TotalCost }); await Save(ct); if (tx is not null) await tx.CommitAsync(ct); return await database.PurchaseReceipts.AsNoTracking().Include(x => x.Lines).SingleAsync(x => x.Id == entity.Id, ct);
    }
    public async Task<ProcurementPage<PurchaseReceipt>> Receipts(ClaimsPrincipal user, ProcurementListQuery query, CancellationToken ct) { RequireAny(user, TenantPermissions.ProcurementReceivingView); var sites = AccessibleSites(user, TenantPermissions.ProcurementReceivingView); var source = database.PurchaseReceipts.AsNoTracking().Include(x => x.Lines).Include(x => x.PurchaseOrder).ThenInclude(x => x!.Supplier).Where(x => x.PurchaseOrder != null && sites.Contains(x.PurchaseOrder.SiteId)); if (query.SiteId is { } site) source = source.Where(x => x.PurchaseOrder!.SiteId == site); if (!string.IsNullOrWhiteSpace(query.Search)) { var s = query.Search.Trim().ToLower(); source = source.Where(x => x.ReceiptNumber.ToLower().Contains(s) || x.PurchaseOrder!.Number.ToLower().Contains(s)); } return await Page(source.OrderByDescending(x => x.CreatedAtUtc), query, ct); }
    public async Task<IReadOnlyList<ProcurementActivity>> Activities(ClaimsPrincipal user, string entityType, Guid entityId, CancellationToken ct) { RequireAny(user, TenantPermissions.ProcurementView); if (entityType == nameof(PurchaseRequisition)) { var site = await database.PurchaseRequisitions.Where(x => x.Id == entityId).Select(x => (Guid?)x.SiteId).SingleOrDefaultAsync(ct) ?? throw new ResourceNotFoundException("Purchase requisition was not found."); RequireSite(user, TenantPermissions.ProcurementView, site); } else if (entityType == nameof(PurchaseOrder)) { var site = await database.PurchaseOrders.Where(x => x.Id == entityId).Select(x => (Guid?)x.SiteId).SingleOrDefaultAsync(ct) ?? throw new ResourceNotFoundException("Purchase order was not found."); RequireSite(user, TenantPermissions.ProcurementView, site); } else if (entityType == nameof(PurchaseReceipt)) { var site = await database.PurchaseReceipts.Where(x => x.Id == entityId && x.PurchaseOrder != null).Select(x => (Guid?)x.PurchaseOrder!.SiteId).SingleOrDefaultAsync(ct) ?? throw new ResourceNotFoundException("Purchase receipt was not found."); RequireSite(user, TenantPermissions.ProcurementView, site); } else if (entityType == nameof(Supplier)) RequireTenant(user, TenantPermissions.ProcurementView); else throw new ValidationException("Procurement activity type is invalid."); return await database.ProcurementActivities.AsNoTracking().Include(x => x.ActorUser).Where(x => x.EntityType == entityType && x.EntityId == entityId).OrderByDescending(x => x.OccurredAtUtc).ToListAsync(ct); }

    private async Task<PurchaseOrder> ChangeOrder(ClaimsPrincipal user, Guid id, WorkflowInput input, PurchaseOrderStatus expected, PurchaseOrderStatus next, string action, CancellationToken ct) { var entity = await OrderEntity(id, true, ct); RequireSite(user, TenantPermissions.ProcurementPurchaseOrdersManage, entity.SiteId); Version(entity.Version, input.Version); if (entity.Status != expected) throw new ConflictException($"Purchase order must be {expected} for this action."); Change(entity, next, action, input.Comment, user); if (next == PurchaseOrderStatus.Issued) { entity.IssuedById = Actor(user); entity.IssuedAtUtc = Now; } await Save(ct); return entity; }
    private void Change(PurchaseOrder entity, PurchaseOrderStatus next, string action, string? comment, ClaimsPrincipal user) { var from = entity.Status; entity.Status = next; entity.Version = Guid.NewGuid(); Activity(nameof(PurchaseOrder), entity.Id, action, from.ToString(), next.ToString(), comment, user); }
    private async Task ApplyOrder(PurchaseOrder entity, PurchaseOrderInput input, ClaimsPrincipal user, bool updating, CancellationToken ct) { entity.OrderDate = input.OrderDate; entity.ExpectedDeliveryDate = input.ExpectedDeliveryDate; entity.Currency = Currency(input.Currency); entity.PaymentTerms = Clean(input.PaymentTerms); entity.Notes = Clean(input.Notes); entity.Subtotal = 0; foreach (var row in input.Lines) { Positive(row.Quantity, "Ordered quantity"); if (row.UnitPrice < 0) throw new ValidationException("Unit price cannot be negative."); var part = await database.SpareParts.SingleOrDefaultAsync(x => x.Id == row.PartId && x.IsActive, ct) ?? throw new ValidationException("An active spare part is required."); PurchaseRequisitionLine? source = null; if (row.SourceRequisitionLineId is { } sourceId) { source = await database.PurchaseRequisitionLines.Include(x => x.Requisition).SingleOrDefaultAsync(x => x.Id == sourceId, ct) ?? throw new ValidationException("Source requisition line was not found."); if (source.PartId != row.PartId || source.Requisition?.SiteId != input.SiteId || source.Requisition.TargetWarehouseId != input.DestinationWarehouseId || source.Requisition.Status is not (PurchaseRequisitionStatus.Approved or PurchaseRequisitionStatus.PartiallyConverted)) throw new ValidationException("Source requisition line is not eligible for this purchase order."); if (source.ConvertedQuantity + row.Quantity > source.RequestedQuantity) throw new ConflictException("Purchase-order quantity exceeds the remaining approved requisition quantity."); source.ConvertedQuantity += row.Quantity; } var subtotal = Money(row.Quantity * row.UnitPrice); entity.Lines.Add(new() { Id = Guid.NewGuid(), TenantId = TenantId, PurchaseOrderId = entity.Id, PartId = part.Id, SourceRequisitionLineId = source?.Id, SupplierPartNumber = Clean(row.SupplierPartNumber), OrderedQuantity = row.Quantity, UnitOfMeasure = part.UnitOfMeasure, UnitPrice = Unit(row.UnitPrice), LineSubtotal = subtotal }); entity.Subtotal += subtotal; } entity.Subtotal = Money(entity.Subtotal); }
    private async Task RestoreConversions(IEnumerable<PurchaseOrderLine> lines, CancellationToken ct) { foreach (var line in lines.Where(x => x.SourceRequisitionLineId != null)) { var source = await database.PurchaseRequisitionLines.SingleAsync(x => x.Id == line.SourceRequisitionLineId, ct); source.ConvertedQuantity -= line.OrderedQuantity; } }
    private async Task RefreshRequisitionStatuses(IEnumerable<PurchaseOrderLine> lines, ClaimsPrincipal user, CancellationToken ct) { var ids = lines.Where(x => x.SourceRequisitionLineId != null).Select(x => x.SourceRequisitionLineId!.Value).ToArray(); var requisitionIds = await database.PurchaseRequisitionLines.Where(x => ids.Contains(x.Id)).Select(x => x.RequisitionId).Distinct().ToListAsync(ct); foreach (var id in requisitionIds) { var request = await database.PurchaseRequisitions.Include(x => x.Lines).SingleAsync(x => x.Id == id, ct); var next = request.Lines.All(x => x.ConvertedQuantity == x.RequestedQuantity) ? PurchaseRequisitionStatus.Converted : request.Lines.Any(x => x.ConvertedQuantity > 0) ? PurchaseRequisitionStatus.PartiallyConverted : PurchaseRequisitionStatus.Approved; if (request.Status != next) Transition(request, next, "Requisition.ConversionChanged", null, user); } }
    private void Transition(PurchaseRequisition entity, PurchaseRequisitionStatus next, string action, string? comment, ClaimsPrincipal user) { var from = entity.Status; entity.Status = next; entity.Version = Guid.NewGuid(); Activity(nameof(PurchaseRequisition), entity.Id, action, from.ToString(), next.ToString(), comment, user); }
    private async Task ValidateSiteWarehouse(ClaimsPrincipal user, string permission, Guid siteId, Guid warehouseId, CancellationToken ct) { RequireSite(user, permission, siteId); _ = await database.Sites.SingleOrDefaultAsync(x => x.Id == siteId && x.IsActive, ct) ?? throw new ValidationException("An active site is required."); _ = await database.Warehouses.SingleOrDefaultAsync(x => x.Id == warehouseId && x.SiteId == siteId && x.IsActive, ct) ?? throw new ValidationException("An active warehouse in the selected site is required."); }
    private async Task ValidateRequisitionLines(IReadOnlyList<RequisitionLineInput> lines, CancellationToken ct) { if (lines.Count == 0) throw new ValidationException("At least one requisition line is required."); if (lines.Select(x => x.PartId).Distinct().Count() != lines.Count) throw new ValidationException("A spare part can appear only once."); foreach (var line in lines) { Positive(line.Quantity, "Requested quantity"); if (line.EstimatedUnitPrice < 0) throw new ValidationException("Estimated unit price cannot be negative."); _ = await database.SpareParts.SingleOrDefaultAsync(x => x.Id == line.PartId && x.IsActive, ct) ?? throw new ValidationException("An active spare part is required."); if (line.SuggestedSupplierId is { } supplier) _ = await ActiveSupplier(supplier, ct); } }
    private void AddRequisitionLines(PurchaseRequisition entity, IEnumerable<RequisitionLineInput> lines) { foreach (var line in lines) { var part = database.SpareParts.Local.Single(x => x.Id == line.PartId); entity.Lines.Add(new() { Id = Guid.NewGuid(), TenantId = TenantId, RequisitionId = entity.Id, PartId = line.PartId, RequestedQuantity = line.Quantity, UnitOfMeasure = part.UnitOfMeasure, SuggestedSupplierId = line.SuggestedSupplierId, EstimatedUnitPrice = line.EstimatedUnitPrice is null ? null : Unit(line.EstimatedUnitPrice.Value), EstimatedTotal = Money(line.Quantity * (line.EstimatedUnitPrice ?? 0)), Notes = Clean(line.Notes) }); } }
    private async Task<PurchaseRequisition> RequisitionEntity(Guid id, bool tracking, CancellationToken ct) { IQueryable<PurchaseRequisition> source = database.PurchaseRequisitions.Include(x => x.Site).Include(x => x.TargetWarehouse).Include(x => x.RequestedBy).Include(x => x.ReviewedBy).Include(x => x.Lines).ThenInclude(x => x.Part).Include(x => x.Lines).ThenInclude(x => x.SuggestedSupplier); if (!tracking) source = source.AsNoTracking(); return await source.SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new ResourceNotFoundException("Purchase requisition was not found."); }
    private async Task<PurchaseOrder> OrderEntity(Guid id, bool tracking, CancellationToken ct) { IQueryable<PurchaseOrder> source = database.PurchaseOrders.Include(x => x.Supplier).Include(x => x.Site).Include(x => x.DestinationWarehouse).Include(x => x.Lines).ThenInclude(x => x.Part).Include(x => x.Lines).ThenInclude(x => x.SourceRequisitionLine); if (!tracking) source = source.AsNoTracking(); return await source.SingleOrDefaultAsync(x => x.Id == id, ct) ?? throw new ResourceNotFoundException("Purchase order was not found."); }
    private Task<Supplier> ActiveSupplier(Guid id, CancellationToken ct) => database.Suppliers.SingleOrDefaultAsync(x => x.Id == id && x.Status == SupplierStatus.Active, ct).ContinueWith(x => x.Result ?? throw new ValidationException("An active supplier is required."), ct);
    private Task<string> NextNumber(string type, CancellationToken ct) => TenantDocumentNumber.Next(database, TenantId, Now, type, ct);
    private void Activity(string type, Guid id, string action, string? from, string? to, string? comment, ClaimsPrincipal user) => database.ProcurementActivities.Add(new() { Id = Guid.NewGuid(), TenantId = TenantId, EntityType = type, EntityId = id, Action = action, FromStatus = from, ToStatus = to, Comment = Clean(comment), ActorUserId = Actor(user), OccurredAtUtc = Now });
    private Guid[] AccessibleSites(ClaimsPrincipal user, string permission) => scopes.HasTenantAccess(user, permission) ? database.Sites.Select(x => x.Id).ToArray() : GrantedSites(user, permission);
    private void RequireTenant(ClaimsPrincipal user, string permission) { if (!scopes.HasTenantAccess(user, permission)) throw new UnauthorizedAccessException("Tenant-wide permission is required."); }
    private void RequireAny(ClaimsPrincipal user, string permission) { if (!scopes.HasTenantAccess(user, permission) && GrantedSites(user, permission).Length == 0) throw new UnauthorizedAccessException("Procurement access is required."); }
    private void RequireSite(ClaimsPrincipal user, string permission, Guid site) { if (!scopes.HasAccess(user, permission, site)) throw new UnauthorizedAccessException("The requested site is outside the granted scope."); }
    private static Guid[] GrantedSites(ClaimsPrincipal user, string permission) => user.FindAll(TenantClaims.Grant).Select(x => x.Value.Split('|')).Where(x => x.Length == 3 && x[0] == permission && x[1] == nameof(AccessScopeKind.Site) && Guid.TryParse(x[2], out _)).Select(x => Guid.Parse(x[2])).Distinct().ToArray();
    private async Task<IDbContextTransaction?> Transaction(CancellationToken ct) => database.Database.IsRelational() && database.Database.CurrentTransaction is null ? await database.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct) : null;
    private async Task Save(CancellationToken ct) { try { await database.SaveChangesAsync(ct); } catch (DbUpdateConcurrencyException ex) { throw new ConflictException($"The record changed concurrently ({string.Join(", ", ex.Entries.Select(x => x.Metadata.ClrType.Name))}). Refresh and retry."); } catch (DbUpdateException ex) when (ex.InnerException is not null) { throw new ConflictException("The procurement operation conflicts with current data or a previous request."); } }
    private static async Task<ProcurementPage<T>> Page<T>(IQueryable<T> source, ProcurementListQuery query, CancellationToken ct) { var page = Math.Max(1, query.Page); var size = Math.Clamp(query.PageSize, 1, 100); var total = await source.CountAsync(ct); return new(await source.Skip((page - 1) * size).Take(size).ToListAsync(ct), page, size, total); }
    private static void ValidateSupplier(SupplierInput input) { Required(input.Code, "Supplier code"); Required(input.NameEn, "English name"); Currency(input.DefaultCurrency); if (!string.IsNullOrWhiteSpace(input.Email) && !new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(input.Email)) throw new ValidationException("Email is invalid."); }
    private static void ValidateRequisition(RequisitionInput input) { if (!Enum.IsDefined(input.Priority)) throw new ValidationException("Priority is invalid."); Required(input.BusinessJustification, "Business justification"); if (input.NeedByDate < input.RequestDate) throw new ValidationException("Need-by date cannot be before the request date."); }
    private static void ValidateOrder(PurchaseOrderInput input) { if (input.Lines.Count == 0) throw new ValidationException("At least one purchase-order line is required."); if (input.ExpectedDeliveryDate < input.OrderDate) throw new ValidationException("Expected delivery cannot be before the order date."); Currency(input.Currency); }
    private static void Apply(Supplier x, SupplierInput i) { x.NameEn = Required(i.NameEn, "English name"); x.NameAr = Clean(i.NameAr); x.ContactPerson = Clean(i.ContactPerson); x.Email = Clean(i.Email); x.Phone = Clean(i.Phone); x.AlternatePhone = Clean(i.AlternatePhone); x.TaxNumber = Clean(i.TaxNumber); x.CommercialRegistrationNumber = Clean(i.CommercialRegistrationNumber); x.Address = Clean(i.Address); x.City = Clean(i.City); x.Country = Clean(i.Country); x.Website = Clean(i.Website); x.PaymentTerms = Clean(i.PaymentTerms); x.DefaultCurrency = Currency(i.DefaultCurrency); x.Notes = Clean(i.Notes); }
    private static void Apply(PurchaseRequisition x, RequisitionInput i) { x.RequestDate = i.RequestDate; x.NeedByDate = i.NeedByDate; x.Priority = i.Priority; x.BusinessJustification = Required(i.BusinessJustification, "Business justification"); x.Notes = Clean(i.Notes); }
    private static Guid Actor(ClaimsPrincipal user) => Guid.TryParse(user.FindFirstValue("sub"), out var id) ? id : throw new UnauthorizedAccessException();
    private static Guid Derive(Guid request, Guid line) { var bytes = SHA256.HashData(Encoding.UTF8.GetBytes($"{request:N}:{line:N}")); return new Guid(bytes.AsSpan(0, 16)); }
    private static string Required(string? value, string name) => string.IsNullOrWhiteSpace(value) ? throw new ValidationException($"{name} is required.") : value.Trim();
    private static string Code(string? value) => Required(value, "Code").ToUpperInvariant();
    private static string Currency(string? value) { var result = Required(value, "Currency").ToUpperInvariant(); if (result.Length != 3 || !result.All(char.IsLetter)) throw new ValidationException("Currency must be a three-letter code."); return result; }
    private static string? Clean(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
    private static decimal Money(decimal value) => decimal.Round(value, 2, MidpointRounding.AwayFromZero);
    private static decimal Unit(decimal value) => decimal.Round(value, 4, MidpointRounding.AwayFromZero);
    private static void Positive(decimal value, string name) { if (value <= 0) throw new ValidationException($"{name} must be greater than zero."); }
    private static void Version(Guid current, Guid supplied) { if (supplied == Guid.Empty || current != supplied) throw new ConflictException("The record was changed by another user."); }
}
